import { expect } from '@std/expect';
import { join } from '@std/path';

import type { HarnessConnector } from '../../src/harness/connector.ts';
import type { Message } from '../../src/harness/runner/runner.ts';

// Independent native protocol fixtures, never generated by the connector under test.
const protocols = {
    codex: {
        answer:
            '{"type":"item.completed","item":{"type":"agent_message","text":"Earlier"}}\n' +
            '{"type":"item.completed","item":{"type":"agent_message","text":"Final 🐈"}}\n',
        success: '{"type":"turn.completed","usage":{}}\n',
        failure: '{"type":"turn.failed","error":{"message":"native failure"}}\n',
    },
    claude: {
        answer: '{"type":"assistant","message":{"content":[{"type":"text","text":"Earlier"}]}}\n',
        success: '{"type":"result","subtype":"success","is_error":false,"result":"Final 🐈"}\n',
        failure:
            '{"type":"result","subtype":"error_during_execution","is_error":true,"errors":["native failure"]}\n',
    },
};

type Launch = { args: string[]; cwd: string; pid: number; home: string; prompt: string };
type FakeOptions = { output?: string; code?: number; hang?: boolean; wait?: boolean };
interface Fake extends AsyncDisposable {
    root: string;
    cwd: string;
    configure(options?: FakeOptions): Promise<void>;
    launch(): Promise<Launch>;
}

async function fixture(name: keyof typeof protocols): Promise<Fake> {
    const root = await Deno.makeTempDir();
    const previous = Deno.env.get('PATH') ?? '';
    const configHome = Deno.env.get(name === 'codex' ? 'CODEX_HOME' : 'CLAUDE_CONFIG_DIR');
    const configKey = name === 'codex' ? 'CODEX_HOME' : 'CLAUDE_CONFIG_DIR';
    await Deno.mkdir(join(root, 'cwd'));
    const script = join(root, 'fake.ts');
    await Deno.writeTextFile(
        script,
        `
const config = JSON.parse(await Deno.readTextFile(${JSON.stringify(join(root, 'config.json'))}));
await Deno.writeTextFile(${JSON.stringify(join(root, 'launch.json'))}, JSON.stringify({
    args: Deno.args, cwd: Deno.cwd(), pid: Deno.pid,
    home: Deno.env.get(${JSON.stringify(configKey)}),
    prompt: await new Response(Deno.stdin.readable).text(),
}));
const encoder = new TextEncoder();
if (config.hang) {
    await Deno.stdout.write(encoder.encode('ready'));
    setInterval(() => {}, 1000);
} else {
    const text = encoder.encode(config.output);
    for (const byte of text) {
        await Deno.stdout.write(new Uint8Array([byte]));
        await new Promise(resolve => setTimeout(resolve, 1));
    }
    await Deno.stderr.write(encoder.encode('native diagnostic 🐈 without newline'));
    if (config.wait) {
        while (true) {
            try { await Deno.stat(${JSON.stringify(join(root, 'release'))}); break; }
            catch { await new Promise(resolve => setTimeout(resolve, 5)); }
        }
    }
    Deno.exit(config.code || 0);
}
`,
    );
    await Deno.writeTextFile(
        join(root, name),
        `#!/bin/sh\nexec '${Deno.execPath()}' run -A '${script}' "$@"\n`,
    );
    await Deno.chmod(join(root, name), 0o755);
    Deno.env.set('PATH', root);
    Deno.env.set(configKey, join(root, 'inherited-home'));
    return {
        root,
        cwd: join(root, 'cwd'),
        async configure(
            options: {
                output?: string;
                code?: number;
                hang?: boolean;
                wait?: boolean;
            } = {},
        ) {
            await Deno.writeTextFile(
                join(root, 'config.json'),
                JSON.stringify({
                    output:
                        protocols[name].answer + protocols[name].success + '{"type":"trailing"}',
                    ...options,
                }),
            );
        },
        async launch(): Promise<{
            args: string[];
            cwd: string;
            pid: number;
            home: string;
            prompt: string;
        }> {
            return JSON.parse(await Deno.readTextFile(join(root, 'launch.json')));
        },
        async [Symbol.asyncDispose]() {
            Deno.env.set('PATH', previous);
            if (configHome === undefined) {
                Deno.env.delete(configKey);
            } else {
                Deno.env.set(configKey, configHome);
            }
            await Deno.remove(root, { recursive: true });
        },
    };
}

export function executionTests(
    name: keyof typeof protocols,
    create: (scope: 'global' | 'local') => HarnessConnector,
): void {
    Deno.test(
        `${name} launches fresh native sessions and preserves raw streams and settings`,
        async () => {
            await using fake = await fixture(name);
            const pids = [];
            for (const [index, options] of [
                {},
                { model: 'native-model', effort: 'native-effort' },
                { effort: 'xhigh' },
            ].entries()) {
                using connector = create(index === 1 ? 'global' : 'local');
                await fake.configure();
                await using runner = await connector.run({
                    cwd: fake.cwd,
                    prompt: '--prompt\nž 🐈',
                    ...options,
                });
                const messages: Message[] = [];
                for await (const message of runner) {
                    messages.push(message);
                }
                expect(await runner.result()).toEqual({ finalMessage: 'Final 🐈' });
                const launch = await fake.launch();
                pids.push(launch.pid);
                expect(launch.cwd).toBe(await Deno.realPath(fake.cwd));
                expect(launch.prompt).toBe('--prompt\nž 🐈');
                expect(launch.home).toBe(join(fake.root, 'inherited-home'));
                const expected =
                    name === 'codex'
                        ? ['exec', '--json']
                        : ['--print', '--output-format', 'stream-json', '--verbose'];
                if ('model' in options) {
                    expected.push('--model', String(options.model));
                }
                if ('effort' in options) {
                    expected.push(
                        ...(name === 'codex'
                            ? [
                                  '--config',
                                  `model_reasoning_effort=${JSON.stringify(options.effort)}`,
                              ]
                            : ['--effort', String(options.effort)]),
                    );
                }
                if (name === 'codex') {
                    expected.push('-');
                }
                expect(launch.args).toEqual(expected);
                expect(
                    messages
                        .filter((m) => m.stream === 'stdout')
                        .map((m) => m.output)
                        .join(''),
                ).toBe(protocols[name].answer + protocols[name].success + '{"type":"trailing"}');
                expect(
                    messages
                        .filter((m) => m.stream === 'stderr')
                        .map((m) => m.output)
                        .join(''),
                ).toBe('native diagnostic 🐈 without newline');
                expect(messages.some((m) => !m.output.endsWith('\n'))).toBe(true);
                for (const message of messages) {
                    expect(message.timestamp).toMatch(/^\d{4}-\d\d-\d\dT\d\d:\d\d:\d\d\.\d{3}Z$/);
                }
            }
            expect(new Set(pids).size).toBe(3);
        },
    );

    Deno.test(`${name} rejects launch, process, and protocol failures`, async () => {
        await using fake = await fixture(name);
        using connector = create('local');
        await expect(
            connector.run({
                cwd: join(fake.root, 'absent'),
                prompt: '',
                signal: new AbortController().signal,
            }),
        ).rejects.toThrow();
        for (const options of [
            { code: 9 },
            { output: protocols[name].failure + protocols[name].success },
            { output: 'not json\nnull\n{}\n' },
            { output: protocols[name].answer },
            {
                output:
                    name === 'codex'
                        ? '{"type":"turn.completed"}\n'
                        : '{"type":"result","subtype":"success","is_error":false}\n',
            },
            {
                output:
                    name === 'codex'
                        ? '{"type":"error","message":"failure"}\n'
                        : '{"type":"result","subtype":"success","is_error":true,"result":"bad"}\n',
            },
        ]) {
            await fake.configure(options);
            await using runner = await connector.run({ cwd: fake.cwd, prompt: '' });
            await expect(runner.result()).rejects.toThrow();
            await expect(
                (async () => {
                    for await (const _ of runner) {
                        /* drain */
                    }
                })(),
            ).rejects.toThrow();
        }
    });

    Deno.test(`${name} waits for exit and drains both streams before completion`, async () => {
        await using fake = await fixture(name);
        await fake.configure({ wait: true });
        using connector = create('local');
        await using runner = await connector.run({ cwd: fake.cwd, prompt: 'test' });
        let completed = false;
        let resultCompleted = false;
        const stderr = Promise.withResolvers<void>();
        const reading = (async () => {
            const messages = [];
            for await (const message of runner) {
                messages.push(message);
                if (message.stream === 'stderr') {
                    stderr.resolve();
                }
            }
            completed = true;
            return messages;
        })();
        const result = runner.result().then((value) => {
            resultCompleted = true;
            return value;
        });
        void reading.catch(() => {});
        void result.catch(() => {});
        await stderr.promise;
        await new Promise((resolve) => setTimeout(resolve, 20));
        expect(completed).toBe(false);
        expect(resultCompleted).toBe(false);
        await Deno.writeTextFile(join(fake.root, 'release'), '');
        expect(await result).toEqual({ finalMessage: 'Final 🐈' });
        const messages = await reading;
        expect(completed).toBe(true);
        expect(messages.some((m) => m.stream === 'stderr')).toBe(true);
    });

    Deno.test(
        `${name} cancels before launch and stops and awaits children on abort or disposal`,
        async () => {
            await using fake = await fixture(name);
            using connector = create('local');
            const aborted = AbortSignal.abort();
            await expect(
                connector.run({ cwd: fake.cwd, prompt: '', signal: aborted }),
            ).rejects.toThrow();
            for (const mode of ['abort', 'dispose', 'break'] as const) {
                await fake.configure({ hang: true });
                const controller = new AbortController();
                await using runner = await connector.run({
                    cwd: fake.cwd,
                    prompt: '',
                    signal: controller.signal,
                });
                const iterator = runner[Symbol.asyncIterator]();
                expect((await iterator.next()).value.output).toBe('ready');
                const { pid } = await fake.launch();
                if (mode === 'abort') {
                    controller.abort();
                } else if (mode === 'dispose') {
                    await runner[Symbol.asyncDispose]();
                } else {
                    await iterator.return?.();
                }
                await expect(runner.result()).rejects.toThrow();
                if (mode !== 'break') {
                    await iterator.return?.();
                }
                expect(() => Deno.kill(pid, 'SIGCONT')).toThrow();
            }
        },
    );
}
